// index.mjs: the library index (LIBRARY.md §4.1-4.2; BUILD-ORDER step 1). One row per item of every layer:
//   {id, layer, version, status, line, tokens, tags, shape, bm25, untrusted, executable}
// `line` is the only form in which a non-expanded item reaches a model: generated by code from the item's fields
// (never an author's free text), at most INDEX_LINE_MAX tokens by the calibrated counter (tokens.mjs). Text from an
// untrusted field (a wrapped skill's name or description, a corpus summary) appears only behind the ‹untrusted› marker.
// `shape` is the item's 0/1 vector over SHAPE_FEATURES (§4.2); `bm25` is the lower-cased text the BM25 arm searches
// (line + when[] questions + task template + tags).
import { countTokens } from './tokens.mjs';
import { shapeLabel } from './schema.mjs';

export const INDEX_LINE_MAX = 30;
export const UNTRUSTED_MARK = '‹untrusted›';
// LIBRARY §4.2: shape features and the L1 patterns each points to.
export const SHAPE_FEATURES = Object.freeze({
  itemLists: ['P12', 'P13', 'P53'],
  freeText: ['P03', 'P07', 'P13', 'P06'],
  multiSource: ['P16', 'P17'],
  conventionsInProse: ['P03'],
  outputShape: ['P12', 'P15'],
  effectVerbs: ['P02', 'P04', 'P08', 'P32'],
  timeWords: ['P36', 'P34', 'P21', 'P33'],
  humanWords: ['P32', 'P55', 'P09'],
  verifiable: ['P20', 'P47'],
  sizeBand: ['P51', 'P19'],
});
const FEATURE_NAMES = Object.keys(SHAPE_FEATURES);
const EFFECT_VERBS = ['send', 'post', 'write', 'delete', 'pay', 'notify'];
const TIME_WORDS = ['every', 'daily', 'cron', 'when', 'after', 'until'];
const HUMAN_WORDS = ['approve', 'ask', 'confirm', 'review'];
const CONVENTION_RE = /\b(DMY|MDY|YMD|ISO|dd\/mm|mm\/dd|day[- ]first|month[- ]first|currency|cents|minor units|decimal comma|USD|EUR|GBP|JPY|kg|lb|percent)\b/i;
const PROSE_MIN_WORDS = 12;   // experiments/jit/profile.mjs PARAMS.proseMinWords

// ---- the one-line index entry ----
// fields: [{text, keep (never dropped), drop (lower drops first), trim (may lose trailing words)}]. Optional fields are
// dropped lowest-first until the line fits; then trimmable kept fields lose trailing words. Throws if it cannot fit.
export function fitLine(fields, max = INDEX_LINE_MAX) {
  let live = fields.filter(f => f.text != null && f.text !== '');
  const render = () => live.map(f => f.text).join(' | ');
  for (const f of [...live].filter(f => !f.keep).sort((a, b) => (a.drop ?? 0) - (b.drop ?? 0))) {
    if (countTokens(render()) <= max) break;
    live = live.filter(x => x !== f);
  }
  for (const f of live.filter(f => f.trim)) {
    while (countTokens(render()) > max && f.text.split(' ').length > 1) f.text = f.text.split(' ').slice(0, -1).join(' ').replace(/[,;:]$/, '') + '…';
  }
  const line = render();
  if (countTokens(line) > max) throw new Error(`index: cannot fit a line within ${max} tokens: ${line}`);
  return line;
}
const hash6 = h => String(h).replace(/^sha256:/, '').slice(0, 6);
const marked = (item, field, text) => ((item.untrusted ?? []).includes(field) ? `${UNTRUSTED_MARK} ${text}` : text);

export function lineOfL1(p) {
  const ev = p.support ?? {};
  return fitLine([
    { text: `${p.id} ${String(p.short).replace(/-/g, ' ')}`, keep: true, trim: true },
    { text: p.family, drop: 3 },
    { text: p.gist, drop: 6, trim: true },
    { text: p.tier ? `tier ${p.tier}` : null, drop: 5 },
    { text: p.slots ? `slots ${p.slots.length}` : null, drop: 1 },
    { text: ev.grade ? `ev ${ev.grade}` : null, drop: 4 },
    { text: ev.items != null ? `${ev.items}/${ev.platforms}p` : null, drop: 0 },
    { text: `v${p.version ?? 1}`, drop: 2 },
  ]);
}
export function lineOfL2(e) {
  const ev = e.evidence ?? {}, reuse = ev.reuse ?? {};
  return fitLine([
    { text: `C:${hash6(e.hash)}`, keep: true },
    { text: e.name ? marked(e, 'name', e.name) : null, drop: 7, trim: true },
    { text: `in ${shapeLabel(e.contract?.input, 3)} out ${shapeLabel(e.contract?.output, 3)}`, drop: 6 },
    { text: `prof n=${e.profile?.n ?? 0}`, drop: 3 },
    { text: `reuse ${reuse.correct ?? 0} ok/${reuse.wrong ?? 0} bad`, drop: 5 },
    { text: `smiss ${ev.silentMissesPer100 ?? 0}`, drop: 1 },
    { text: e.status, drop: 4 },
    { text: `v${e.version ?? 1}`, drop: 2 },
  ]);
}
export function lineOfL3(b) {
  const eff = b.effect ?? {};
  return fitLine([
    { text: `B:${b.tool}`, keep: true },
    { text: `${eff.kind ?? '?'}, reversible=${eff.reversible ? 'yes' : 'no'}${eff.external ? ', external' : ''}`, drop: 6 },
    { text: b.idempotency?.key ? `idem ${b.idempotency.key}` : 'idem none', drop: 3 },
    { text: b.rateLimit ? `${b.rateLimit}` : null, drop: 1 },
    { text: b.credential ? `cred ${b.credential}` : null, drop: 2 },
  ]);
}
export function lineOfL4(e) {
  const ev = e.evidence ?? {};
  return fitLine([
    { text: `I:${hash6(e.hash)}`, keep: true },
    { text: e.name ? marked(e, 'name', e.name) : null, drop: 7, trim: true },
    { text: e.trigger ? `trigger ${e.trigger.kind ?? 'host'}` : null, drop: 3 },
    { text: `solver C:${hash6(e.solver)}`, drop: 6 },
    { text: e.status, drop: 4 },
    { text: `runs ${ev.runs ?? 0}`, drop: 1 },
    { text: `v${e.version ?? 1}`, drop: 2 },
  ]);
}

// ---- shape/1 (LIBRARY §4.2), from the task alone: code, $0 ----
export function shapeOf(task = {}) {
  const arrays = [], prose = [];
  const walk = (v, p) => {
    if (Array.isArray(v)) { arrays.push({ path: p, n: v.length, keys: v.length && v[0] && typeof v[0] === 'object' ? Object.keys(v[0]) : [] }); v.slice(0, 50).forEach(x => walk(x, `${p}[]`)); }
    else if (v && typeof v === 'object') for (const [k, x] of Object.entries(v)) walk(x, p ? `${p}.${k}` : k);
    else if (typeof v === 'string' && (v.match(/\S+/g) ?? []).length >= PROSE_MIN_WORDS) prose.push({ path: p, text: v });
  };
  walk(task.inputs ?? {}, '');
  for (const [name, text] of Object.entries(task.files ?? {})) if (typeof text === 'string' && (text.match(/\S+/g) ?? []).length >= PROSE_MIN_WORDS) prose.push({ path: `files.${name}`, text });
  const prompt = String(task.prompt ?? '').toLowerCase();
  const words = new Set(prompt.match(/[a-z]+/g) ?? []);
  const jaccard = (a, b) => { const A = new Set(a), B = new Set(b); const i = [...A].filter(x => B.has(x)).length; return A.size + B.size - i ? i / (A.size + B.size - i) : 0; };
  let multi = 0;
  for (let i = 0; i < arrays.length; i++) for (let j = i + 1; j < arrays.length; j++) if (arrays[i].keys.length && jaccard(arrays[i].keys, arrays[j].keys) >= 0.5) multi++;
  const out = /\btotals?\b|\bsum\b/.test(prompt) ? 'totals' : /\breport\b/.test(prompt) ? 'report' : /\beach\b|\bper[- ]item\b|\brows?\b/.test(prompt) ? 'per-item' : null;
  const inputTokens = countTokens(JSON.stringify(task.inputs ?? {}) + Object.values(task.files ?? {}).join('\n'));
  const record = {
    schema: 'shape/1',
    itemLists: { count: arrays.length, maxLength: Math.max(0, ...arrays.map(a => a.n)) },
    freeText: { count: prose.length },
    multiSource: { pairs: multi },
    conventionsInProse: prose.some(p => CONVENTION_RE.test(p.text)),
    outputShape: out,
    effectVerbs: EFFECT_VERBS.filter(w => words.has(w)),
    timeWords: TIME_WORDS.filter(w => words.has(w)),
    humanWords: HUMAN_WORDS.filter(w => words.has(w)),
    verifiable: !!task.outputSchema || /\bschema\b|\btests?\b|\bchecker\b/.test(prompt),
    sizeBand: inputTokens < 2000 ? 'S' : inputTokens < 8000 ? 'M' : 'L',
  };
  record.vector = [record.itemLists.count > 0, record.freeText.count > 0, record.multiSource.pairs > 0, record.conventionsInProse, record.outputShape != null,
    record.effectVerbs.length > 0, record.timeWords.length > 0, record.humanWords.length > 0, record.verifiable, record.sizeBand === 'L'].map(Number);
  return record;
}
// An L1 card's shape vector: 1 where §4.2 says the feature points to it.
export const shapeOfCard = id => FEATURE_NAMES.map(f => Number(SHAPE_FEATURES[f].includes(id)));
// An L2 / L4 item's vector from its contract (what the input looks like), when no task sample is at hand.
export function shapeOfContract(contract = {}) {
  const props = contract.input?.properties ?? {}, arrays = Object.entries(props).filter(([, s]) => s?.type === 'array');
  const keysOf = s => Object.keys(s?.items?.properties ?? {});
  let multi = 0;
  for (let i = 0; i < arrays.length; i++) for (let j = i + 1; j < arrays.length; j++) { const a = keysOf(arrays[i][1]), b = keysOf(arrays[j][1]); if (a.length && a.filter(k => b.includes(k)).length * 2 >= Math.max(a.length, b.length)) multi++; }
  const outArrays = Object.values(contract.output?.properties ?? {}).some(s => s?.type === 'array');
  return [arrays.length > 0, false, multi > 0, false, outArrays, false, false, false, !!contract.output, false].map(Number);
}

const bm25Text = parts => parts.filter(Boolean).join(' ').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();

// ---- build the index rows; writes index.jsonl when a library is given ----
// l1: loadL1() entries; library: openLibrary(); bindings: L3 bindings the host adapter exposes (§3.4).
export function buildIndex({ l1 = [], library = null, bindings = [] } = {}) {
  const rows = [];
  for (const p of l1) {
    const line = lineOfL1(p);
    rows.push({ id: p.id, layer: 'L1', version: p.version ?? 1, status: 'kept', line, tokens: countTokens(line), tags: [p.family, ...(p.tags ?? [])].filter(Boolean),
      shape: shapeOfCard(p.id), bm25: bm25Text([line, p.name, ...(p.when ?? []).map(w => w.instructions)]), untrusted: false, executable: !!p.executable });
  }
  for (const e of library ? library.list() : []) {
    if (['retired', 'revoked'].includes(e.status)) continue;   // they leave the index; their evidence stays (LIBRARY §7.6-7.7)
    const line = e.layer === 'L4' ? lineOfL4(e) : lineOfL2(e);
    const untrustedShown = (e.untrusted ?? []).some(f => e[f] != null && line.includes(String(e[f]).slice(0, 8)));
    rows.push({ id: e.hash, layer: e.layer, version: e.version, status: e.status, line, tokens: countTokens(line), tags: e.tags ?? [],
      shape: e.layer === 'L2' ? shapeOfContract(e.contract) : new Array(FEATURE_NAMES.length).fill(0),
      // Untrusted text is searched only through the marked line, never through its raw field.
      bm25: bm25Text([line, (e.untrusted ?? []).includes('taskTemplate') ? null : e.contract?.taskTemplate, ...(e.tags ?? [])]), untrusted: untrustedShown, executable: e.layer === 'L2' });
  }
  for (const b of bindings) {
    const line = lineOfL3(b);
    rows.push({ id: `B:${b.tool}`, layer: 'L3', version: b.version ?? 1, status: 'kept', line, tokens: countTokens(line), tags: [`effect:${b.effect?.kind ?? 'none'}`],
      shape: new Array(FEATURE_NAMES.length).fill(0), bm25: bm25Text([line]), untrusted: false, executable: false });
  }
  if (library) library.writeIndex(rows);
  return rows;
}
